import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load image via cached loader
  const imageUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const tex = ctx.textureLoader.load(imageUrl);

  // Create plane geometry (1.0 × 0.625 for 512×320 aspect ratio)
  const geometry = new THREE.PlaneGeometry(1, 0.625);

  // Material using TSL texture node
  const colorNode = texture(tex);
  const material = new MeshBasicNodeMaterial({
    colorNode: colorNode,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement
  const pos = config.scenePosition || [2.5, 1.6, 0];
  mesh.position.set(pos[0], pos[1], pos[2]);

  const rot = config.sceneRotation || [0, 0, 0];
  mesh.rotation.set(rot[0], rot[1], rot[2]);

  const scl = config.sceneScale || [1, 1, 1];
  mesh.scale.set(scl[0], scl[1], scl[2]);

  group.add(mesh);

  // Store originals for animation reset
  const origY = mesh.position.y;
  const origSx = mesh.scale.x;
  const origSy = mesh.scale.y;

  // Timeline references
  let hoverTl = null;
  let clickTl = null;

  // Event handlers
  const handlers = {};

  // Hover: rise-in (y +0.15, power3.out, 0.7s)
  handlers.mouseenter = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(mesh.position, {
      y: origY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
      overwrite: 'auto'
    });
  };

  handlers.mouseleave = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(mesh.position, {
      y: origY,
      duration: 0.7,
      ease: 'power3.out',
      overwrite: 'auto'
    });
  };

  // Click: press-down (scale 0.97, back.out, 120ms) + emit navigation
  handlers.click = () => {
    if (clickTl) clickTl.kill();
    clickTl = gsap.timeline();

    clickTl.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out'
    }, 0);

    clickTl.to(mesh.scale, {
      x: origSx,
      y: origSy,
      duration: 0.12,
      ease: 'back.out'
    }, 0.12);

    // Emit navigation event
    if (ctx.emit) {
      ctx.emit('hub-journal.select', { card: group });
    }
  };

  // Focus/blur: accent edge state (parent can read for visual feedback)
  handlers.focus = () => {
    group.userData.focused = true;
  };

  handlers.blur = () => {
    group.userData.focused = false;
  };

  group.userData.handlers = handlers;

  // Cleanup function
  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (clickTl) clickTl.kill();
    geometry.dispose();
    material.dispose();
    tex.dispose();
  };

  return group;
}
